SELECT

FROM merchant

    deleted = 0

        AND shop_name LIKE CONCAT('%', #{shopName}, '%')


        AND address LIKE CONCAT('%', #{shopAddress}, '%')


        AND audit_status = #{auditStatus}


        AND status = #{status}




    LIMIT #{offset}, #{pageSize}
